from collections import defaultdict
from itertools import combinations

def f(N: int, connections: List[Tuple[int, int]], s: str):
    graph = defaultdict(list)
    for a, b in connections:
        graph[a].append(b)
        graph[b].append(a)

    # get connected components
    visited = set()
    def dfs(n, comp):
        visited.add(n)
        comp.append(n)
        for nei in graph[n]:
            if nei not in visited:
                dfs(nei, comp)
    components = []
    for i in range(1, N+1):
        if i not in visited:
            comp = []
            dfs(i, comp)
            components.append(comp)

    # assign color to each node
    color = [0] * (N+1)
    for component in components:
        if len(component) % 2 == 0:
            for n in component:
                color[n] = s[n-1]
        else:
            xor = 0
            for n in component:
                xor ^= int(s[n-1])
            for n in component:
                color[n] = str(int(s[n-1]) ^ xor)

    return ''.join(map(str, color[1:]))


